 $('landingSignIn').onclick=async()=>{$('landingSignIn').disabled=true;try{const {data:sessionData,error:sessionError}=await sb.auth.getSession();if(sessionError)throw sessionError;const session=sessionData.session;if(session){user=session.user;const {data:myProfile,error}=await sb.from('profiles').select('role,name,organization_id,is_active').eq('id',user.id).single();if(error||!myProfile?.is_active){await sb.auth.signOut({scope:'local'});clearAuthenticatedState();throw new Error('Your account is inactive or its profile is unavailable. Contact an administrator.')}profile=myProfile;applyRoleUI();if(myProfile&&['super_admin','platform_admin','organization_head','admin'].includes(myProfile.role)){$('userAdminPanel').classList.remove('hidden');document.querySelectorAll('.admin-nav').forEach(x=>x.classList.remove('hidden'))}$('logoutBtn').classList.remove('hidden');showWorkspace();currentPage='';if(['super_admin','platform_admin'].includes(myProfile.role)){await showPage('organizations')}else{await load();await showPage('dashboard')}}else{$('landingPage').classList.add('hidden');$('loginGate').classList.remove('hidden');$('loginEmployeeId').focus()}}catch(err){say('loginMessage',err.message||'Could not restore your session. Please sign in.');$('landingPage').classList.add('hidden');$('loginGate').classList.remove('hidden')}finally{$('landingSignIn').disabled=false}};
 function hasUnsavedAttendance(){return JSON.stringify(draftAttendance)!==JSON.stringify(attendance)}
 async function showPage(page){if(currentPage==='attendance'&&hasUnsavedAttendance()&&page!==currentPage){if(!confirm('You have unsaved attendance changes. Leave this page and discard them?'))return;clearAttendanceDraft();draftAttendance={...attendance};recoveredPending=false;$('saveRecoveredDraft')?.classList.add('hidden');}if(page===currentPage&&page==='attendance')return;writeWorkspaceState({page});currentPage=page;document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===page));document.querySelectorAll('.mobile-nav-item[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('mobileMoreToggle')?.classList.toggle('active',!['attendance','students','reports','holidays'].includes(page));document.querySelectorAll('.mobile-more-menu [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('mobileMoreMenu')?.classList.add('hidden');$('mobileMoreToggle')?.setAttribute('aria-expanded','false');document.querySelectorAll('[data-page-view]').forEach(x=>x.classList.toggle('hidden',x.dataset.pageView!==page));if(['attendance','students','reports','dashboard'].includes(page))await load();if(page==='reports'){if(!profile?.organization_id){say('saveStatus','Choose an organisation to view its reports.');return}const selectedAttendanceDate=$('attendanceDate').value||today();if(selectedAttendanceDate!==lastReportAttendanceDate){const parts=selectedAttendanceDate.split('-');if(parts.length===3){$('reportYear').value=parts[0];$('reportMonth').value=String(Number(parts[1]));lastReportAttendanceDate=selectedAttendanceDate;}}await renderReportViews();}if(page==='holidays')await renderHolidayPage();if(page==='students')renderDirectory();if(page==='users')await loadUsers();if(page==='organizations')await loadOrganizationRequests();if(page==='batches')await loadBatchPage();if(page==='requests'){await loadRequests();await loadLeftRequests();}if(page==='help')await loadContacts();}
 document.querySelectorAll('.nav-link').forEach(btn=>btn.addEventListener('click',()=>showPage(btn.dataset.page)));
 document.querySelectorAll('[data-open-page]').forEach(btn=>btn.addEventListener('click',()=>showPage(btn.dataset.openPage)));
 document.querySelectorAll('.mobile-nav-item[data-page],.mobile-more-menu [data-page]').forEach(btn=>btn.addEventListener('click',()=>showPage(btn.dataset.page)));
 $('mobileMoreToggle')?.addEventListener('click',()=>{const menu=$('mobileMoreMenu'),open=menu.classList.toggle('hidden')===false;$('mobileMoreToggle').setAttribute('aria-expanded',String(open));$('mobileAccountMenu').classList.add('hidden')});
 $('mobileMenuToggle')?.addEventListener('click',()=>{const menu=$('mobileAccountMenu'),open=menu.classList.toggle('hidden')===false;$('mobileMenuToggle').setAttribute('aria-expanded',String(open));$('mobileMoreMenu').classList.add('hidden')});
 $('mobileLogoutBtn')?.addEventListener('click',()=>$('logoutBtn').click());
 document.addEventListener('click',e=>{if(!e.target.closest('.mobile-account-menu,.mobile-menu-toggle')){$('mobileAccountMenu')?.classList.add('hidden');$('mobileMenuToggle')?.setAttribute('aria-expanded','false')}if(!e.target.closest('.mobile-more-menu,#mobileMoreToggle')){$('mobileMoreMenu')?.classList.add('hidden');$('mobileMoreToggle')?.setAttribute('aria-expanded','false')}});
 showLanding();
 const publicOrgForm=document.querySelector('.org-request-public');
 if(publicOrgForm&&$('registerPanel'))$('registerPanel').appendChild(publicOrgForm);
 $('showRegister')?.addEventListener('click',()=>{$('loginCard')?.classList.add('hidden');$('registerPanel')?.classList.remove('hidden')});
 $('showLogin')?.addEventListener('click',()=>{$('registerPanel')?.classList.add('hidden');$('loginCard')?.classList.remove('hidden')});
 setInterval(tick,1000);connection();addEventListener('online',connection);addEventListener('offline',connection);
 $('loginForm').onsubmit=async e=>{e.preventDefault();if(!sb){say('loginMessage','Admin setup is not complete. Add Supabase settings in config.js first.');return}
  if(offline()){say('loginMessage','Internet connection is required. Please reconnect and try again.');return}const id=$('loginEmployeeId').value.trim(),password=$('loginPassword').value;
  $('loginSubmit').disabled=true;say('loginMessage','Signing in…');
  try{const response=await fetch(cfg.url+'/functions/v1/nkkams-login',{method:'POST',headers:{'Content-Type':'application/json','apikey':cfg.publishableKey},body:JSON.stringify({employee_id:id,password})});
   const data=await response.json();if(!response.ok)throw new Error(data.error||'Sign-in failed.');
   if(!data?.access_token||!data?.refresh_token)throw new Error('Sign-in response was incomplete.');
   const {data:sessionData,error:setError}=await sb.auth.setSession({access_token:data.access_token,refresh_token:data.refresh_token});if(setError)throw setError;
   user=sessionData.user;
   const {data:myProfile,error:profileError}=await sb.from('profiles').select('role,name,organization_id,is_active').eq('id',user.id).single();if(profileError||!myProfile?.is_active){await sb.auth.signOut({scope:'local'});throw new Error('Your account is inactive or its profile is unavailable. Contact an administrator.')}profile=myProfile;applyRoleUI();syncProfileHeader();syncProfileHeader();
   if(myProfile&&['super_admin','platform_admin','organization_head','admin'].includes(myProfile.role)){document.querySelectorAll('.admin-nav').forEach(x=>x.classList.remove('hidden'))}
   showWorkspace();$('logoutBtn').classList.remove('hidden');if(['super_admin','platform_admin'].includes(myProfile.role)){await showPage('organizations')}else{await load();await showPage('dashboard')};
  }catch(err){say('loginMessage',err.message||'Sign-in failed.');}finally{$('loginSubmit').disabled=false}
 };
 $('showBootstrap').onclick=()=> $('bootstrapForm').classList.toggle('hidden');
 $('bootstrapForm').onsubmit=async e=>{
  e.preventDefault();
  const employee_id=$('bootstrapEmployeeId').value.trim().toUpperCase(),name=$('bootstrapName').value.trim(),password=$('bootstrapPassword').value;
  if(password.length<12){say('bootstrapMessage','Use at least 12 characters for your new password.');return}
  $('bootstrapSubmit').disabled=true;say('bootstrapMessage','Creating your first administrator account…');
  try{
   const response=await fetch(cfg.url+'/functions/v1/admin-users',{method:'POST',headers:{'Content-Type':'application/json','apikey':cfg.publishableKey},body:JSON.stringify({action:'bootstrap_super_admin',employee_id,name,password})});
   const result=await response.json();if(!response.ok)throw new Error(result.error||'Could not create administrator account.');
   const loginResponse=await fetch(cfg.url+'/functions/v1/nkkams-login',{method:'POST',headers:{'Content-Type':'application/json','apikey':cfg.publishableKey},body:JSON.stringify({employee_id,password})});
   const loginData=await loginResponse.json();if(!loginResponse.ok)throw new Error(loginData.error||'Account created. Please sign in using your new password.');
   const {data:sessionData,error:setError}=await sb.auth.setSession({access_token:loginData.access_token,refresh_token:loginData.refresh_token});if(setError)throw setError;
   user=sessionData.user;showWorkspace();$('logoutBtn').classList.remove('hidden');$('userAdminPanel').classList.remove('hidden');document.querySelector('.admin-nav').classList.remove('hidden');await load();
  }catch(err){say('bootstrapMessage',err.message||'Administrator setup failed.');}
  finally{$('bootstrapSubmit').disabled=false}
 };
 $('logoutBtn').onclick=async()=>{if(currentPage==='attendance'&&hasUnsavedAttendance()&&!confirm('You have unsaved attendance changes. Sign out and discard them?'))return;const btn=$('logoutBtn');btn.disabled=true;try{if(sb){const {error}=await sb.auth.signOut({scope:'global'});if(error){console.warn('Global sign-out failed; clearing this browser session locally.',error);const localResult=await sb.auth.signOut({scope:'local'});if(localResult.error)throw localResult.error;}}clearAuthenticatedState();}catch(err){console.error('Sign-out failed',err);try{await sb?.auth.signOut({scope:'local'})}catch(localErr){console.error('Local sign-out failed',localErr)}clearAuthenticatedState();say('loginMessage','Your browser session was cleared. If sign-out keeps failing, close this tab and contact an administrator.');}finally{btn.disabled=false}};

 $('saveRecoveredDraft')?.addEventListener('click',async()=>{if(!profile?.organization_id||!activeBatchId)return;const btn=$('saveRecoveredDraft');btn.disabled=true;try{const changed=students.filter(s=>(draftAttendance[s.id]||'')!==(attendance[s.id]||''));const upserts=changed.filter(s=>draftAttendance[s.id]).map(s=>({student_id:s.id,attendance_date:$('attendanceDate').value,status:draftAttendance[s.id],marked_by:user.id,organization_id:s.organization_id}));if(upserts.length){const {error}=await sb.from('attendance').upsert(upserts,{onConflict:'student_id,attendance_date'});if(error)throw error;}for(const s of changed.filter(x=>!draftAttendance[x.id])){const {error}=await sb.from('attendance').delete().eq('student_id',s.id).eq('attendance_date',$('attendanceDate').value);if(error)throw error;}attendance={...draftAttendance};recoveredPending=false;clearAttendanceDraft();btn.classList.add('hidden');render();say('saveStatus','Recovered attendance changes saved successfully.');}catch(e){say('saveStatus','Could not save recovered changes: '+e.message);}finally{btn.disabled=false;}});
 if(!['super_admin','platform_admin','organization_head','admin'].includes(profile?.role))$('addStudent')?.classList.add('hidden');
 $('addStudent').onclick=()=>{resetStudentForm();fillStudentFormBatch();$('studentForm').classList.toggle('hidden')};$('cancelAdd').onclick=()=>{$('studentForm').classList.add('hidden');resetStudentForm()};$('cancelEdit').onclick=()=>{$('studentForm').classList.add('hidden');resetStudentForm()};$('directorySearch').oninput=renderDirectory;$('studentFilter').onchange=renderDirectory;$('directoryBatchFilter').onchange=renderDirectory;$('viewMissingDates')?.addEventListener('click',()=>{$('studentFilter').value='missing_joining';renderDirectory();$('directoryRows').scrollIntoView({behavior:'smooth',block:'start'});});
 $('attendanceBatch')?.addEventListener('change',async()=>{if(hasUnsavedAttendance()&&!confirm('Discard unsaved attendance changes and switch batches?')){$('attendanceBatch').value=activeBatchId;return}activeBatchId=$('attendanceBatch').value;await load()});
 $('studentOrganization')?.addEventListener('change',async()=>{if(!['super_admin','platform_admin'].includes(profile?.role))return;if(hasUnsavedAttendance()&&!confirm('Discard unsaved attendance changes and switch organisations?')){$('studentOrganization').value=profile.organization_id||'';return}const selected=$('studentOrganization').value;if(!selected)return;if($('attendanceOrganization'))$('attendanceOrganization').value=selected;profile.organization_id=selected;profile.organization_name=$('studentOrganization').selectedOptions[0]?.textContent||'Organisation';activeBatchId='';students=[];attendance={};draftAttendance={};await load();});
 $('attendanceOrganization')?.addEventListener('change',async()=>{if(!['super_admin','platform_admin'].includes(profile?.role))return;if(hasUnsavedAttendance()&&!confirm('Discard unsaved attendance changes and switch organisations?')){$('attendanceOrganization').value=profile.organization_id||'';return}const selected=$('attendanceOrganization').value;if(!selected)return;if($('studentOrganization'))$('studentOrganization').value=selected;profile.organization_id=selected;profile.organization_name=$('attendanceOrganization').selectedOptions[0]?.textContent||'Organisation';activeBatchId='';students=[];attendance={};draftAttendance={};await load();});
 $('studentForm').onsubmit=async e=>{e.preventDefault();const id=$('editingStudentId').value;const row={name:$('studentName').value.trim(),employee_id:$('employeeId').value.trim().toUpperCase(),joining_date:$('joiningDate').value||null,left_date:$('leftDate').value||null,is_active:!$('leftDate').value,organization_id:profile?.organization_id,batch_id:$('studentFormBatch').value||null};if(!row.name||!row.employee_id||!row.joining_date||!row.batch_id){say('studentMessage','Name, Employee ID, joining date and batch are required.');return}if(row.left_date&&row.left_date<row.joining_date){say('studentMessage','Leaving date cannot be before joining date.');return}try{const result=id?await sb.from('students').update(row).eq('id',id):await sb.from('students').insert(row);if(result.error)throw result.error;$('studentForm').classList.add('hidden');resetStudentForm();await load();renderDirectory();say('studentMessage','Student record saved. Existing attendance history is preserved.')}catch(err){say('studentMessage',err.message||'Could not save student')}};
 $('search').oninput=render;$('attendanceFilter').onchange=render;$('printDaily').onclick=()=>window.print();$('printMonthly').onclick=()=>window.print();
 const savedDate=readWorkspaceState().attendanceDate;$('attendanceDate').value=savedDate&&savedDate<=today()?savedDate:today();$('attendanceDate').max=today();$('attendanceDate').onchange=async()=>{if($('attendanceDate').value>today()){$('attendanceDate').value=activeAttendanceDate;say('saveStatus','Future attendance is not allowed. You can mark attendance only for today or an earlier date.');return}if(hasUnsavedAttendance()&&!confirm('Discard unsaved attendance changes and open another date?')){$('attendanceDate').value=activeAttendanceDate;return}activeAttendanceDate=$('attendanceDate').value;writeWorkspaceState({attendanceDate:activeAttendanceDate});await loadAttendance()};let activeAttendanceDate=today();
 $('markAllPresent').onclick=markAllPresent;
 $('exportMonthly').onclick=()=>exportReport(false);$('exportIndividual').onclick=()=>exportReport(true);$('exportYearRegister').onclick=exportYearRegister;
 
 async function load(){
 if(!sb)return;
 const isGlobalWorkspace=['super_admin','platform_admin'].includes(profile?.role);
 if(!profile?.organization_id&&!isGlobalWorkspace){
  students=[];batches=[];attendance={};draftAttendance={};render();renderDirectory();
  say('saveStatus','This account is not assigned to an organisation. Contact the Super Admin.');return;
 }
 say('saveStatus','Loading organisation and students…');
 try{
  if(isGlobalWorkspace){
   const orgResult=await adminCall('list_organizations'),orgs=orgResult.organizations||[];const savedOrg=readWorkspaceState().organizationId,preferredOrg=orgs.find(o=>o.id===savedOrg)||(orgs.length===1?orgs[0]:null);if(isGlobalWorkspace&&preferredOrg&&!profile.organization_id){profile.organization_id=preferredOrg.id;profile.organization_name=preferredOrg.name||'';}
   const optionHtml='<option value="">Choose organisation</option>'+orgs.map(o=>'<option value="'+esc(o.id)+'">'+esc(o.name)+'</option>').join('');
   const attendanceOrg=$('attendanceOrganization'),studentOrg=$('studentOrganization');
   if(attendanceOrg){attendanceOrg.innerHTML=optionHtml;attendanceOrg.value=profile.organization_id||'';attendanceOrg.disabled=!orgs.length;}
   if(studentOrg){studentOrg.innerHTML=optionHtml;studentOrg.value=profile.organization_id||'';studentOrg.disabled=!orgs.length;}
   $('attendanceOrgWrap')?.classList.remove('hidden');$('studentOrgWrap')?.classList.remove('hidden');
  }else{
   $('attendanceOrgWrap')?.classList.add('hidden');$('studentOrgWrap')?.classList.add('hidden');
  }
  if(!profile?.organization_id){
   batches=[];students=[];attendance={};draftAttendance={};
   const select=$('attendanceBatch');if(select){select.innerHTML='<option value="">Choose organisation first</option>';select.disabled=true;}directoryStudents=[];
   fillReports();renderDirectory();render();
   say('saveStatus','Choose an organisation to load its batches and students.');return;
  }
  const batchResult=await adminCall('list_batches',{organization_id:profile.organization_id});
  batches=(batchResult.batches||[]).filter(b=>b.is_active!==false);
  const previous=activeBatchId||readWorkspaceState().batchId||'';
  activeBatchId=batches.some(b=>b.id===previous)?previous:(batches.find(b=>b.name==='SMT-02')?.id||batches[0]?.id||'');
  const attendanceBatch=$('attendanceBatch');if(attendanceBatch){attendanceBatch.innerHTML='<option value="">'+(batches.length?'Choose batch':'No batches available')+'</option>'+batches.map(b=>'<option value="'+esc(b.id)+'">'+esc(b.name)+'</option>').join('');attendanceBatch.value=activeBatchId;attendanceBatch.disabled=!batches.length;}writeWorkspaceState({organizationId:profile.organization_id,batchId:activeBatchId});
  const directoryResult=await sb.from('students').select('id,name,employee_id,joining_date,left_date,is_active,organization_id,batch_id').eq('organization_id',profile.organization_id).order('name');if(directoryResult.error)throw directoryResult.error;directoryStudents=directoryResult.data||[];fillStudentFormBatch();renderDirectory();
  if(!activeBatchId){
   students=[];attendance={};draftAttendance={};fillReports();renderDirectory();render();
   say('saveStatus','No active batches found. Create a batch to add students.');return;
  }
  const {data,error}=await sb.from('students').select('id,name,employee_id,joining_date,left_date,is_active,organization_id,batch_id').eq('organization_id',profile.organization_id).eq('batch_id',activeBatchId).order('name');
  if(error)throw error;
  students=data||[];fillReports();renderDirectory();await loadAttendance();
  say('saveStatus',students.length?(offline()?'Offline mode':'Synced'):'No students are assigned to '+(batches.find(b=>b.id===activeBatchId)?.name||'this batch')+'. Check the batch assignment or add students.');
 }catch(e){
  students=[];batches=[];activeBatchId='';attendance={};draftAttendance={};const select=$('attendanceBatch');if(select){select.innerHTML='<option value="">Unable to load batches</option>';select.disabled=true;}directoryStudents=[];renderDirectory();render();
  say('saveStatus','Could not load this organisation: '+(e.message||'Unknown database error'));
  console.error('NKKAMS organisation load failed',e);
 }
}
async function loadAttendance(){if(!sb||!profile?.organization_id){attendance={};draftAttendance={};render();say('saveStatus','Choose an organisation and batch first.');return}const date=$('attendanceDate').value||today();$('attendanceDate').value=date;if(!students.length){attendance={};draftAttendance={};holidays=[];render();renderHolidays();say('saveStatus','No students are assigned to the selected batch.');return}say('saveStatus','Loading attendance…');const {data,error}=await sb.from('attendance').select('student_id,status').eq('organization_id',profile.organization_id).eq('attendance_date',date).in('student_id',students.map(s=>s.id));if(error){attendance={};draftAttendance={};render();say('saveStatus','Attendance could not be loaded: '+error.message);console.error('NKKAMS attendance query failed',error);return}attendance=Object.fromEntries((data||[]).map(x=>[x.student_id,x.status]));draftAttendance={...attendance};const recovered=readAttendanceDraft();if(recovered&&recovered.userId===user?.id&&recovered.organizationId===profile.organization_id&&recovered.batchId===activeBatchId&&recovered.date===date&&recovered.draft&&typeof recovered.draft==='object'){draftAttendance={...draftAttendance,...recovered.draft};if(JSON.stringify(draftAttendance)!==JSON.stringify(attendance)){recoveredPending=true;$('saveRecoveredDraft')?.classList.remove('hidden');}}const {data:hs,error:he}=await sb.from('holidays').select('holiday_date,reason').eq('organization_id',profile.organization_id).eq('holiday_date',date).maybeSingle();if(he&&he.code!=='PGRST116'){say('saveStatus','Holiday information could not be loaded: '+he.message);console.error('NKKAMS holiday query failed',he);return}holidays=hs?[hs]:[];render();renderHolidays();say('saveStatus',recoveredPending?'Recovered interrupted attendance changes. Select Save recovered changes to finish saving them.':(offline()?'Offline mode':'Synced'));}
 function resetStudentForm(){if(!$('studentForm'))return;$('studentForm').reset();$('editingStudentId').value='';$('studentSave').textContent='Save student';$('cancelAdd').classList.remove('hidden');$('cancelEdit').classList.add('hidden');say('studentMessage','')}
 function editStudent(id){const s=directoryStudents.find(x=>x.id===id);if(!s)return;$('editingStudentId').value=s.id;$('studentFormBatch').value=s.batch_id||'';$('studentName').value=s.name;$('employeeId').value=s.employee_id;$('joiningDate').value=s.joining_date||'';$('leftDate').value=s.left_date||'';$('studentSave').textContent='Update student';$('cancelAdd').classList.add('hidden');$('cancelEdit').classList.remove('hidden');$('studentForm').classList.remove('hidden');$('studentName').focus()}
 async function markStudentLeft(id){if(!['super_admin','platform_admin','organization_head','admin'].includes(profile?.role)){alert('Only an Admin can mark a student as Left.');return}const s=directoryStudents.find(x=>x.id===id);if(!s)return;const overlay=document.createElement('div');overlay.className='left-date-overlay';overlay.innerHTML='<div class="left-date-dialog"><h3>Mark '+esc(s.name)+' as Left</h3><p class="muted">Choose the student’s final date. Earlier attendance will be preserved.</p><label class="date-input"><span>Leaving date</span><input type="date" id="leftDateChoice" value="'+today()+'"></label><div class="left-date-actions"><button type="button" class="secondary" data-cancel-left>Cancel</button><button type="button" class="primary" data-confirm-left>Confirm</button></div></div>';document.body.appendChild(overlay);const dateInput=overlay.querySelector('#leftDateChoice');initCustomDatePickers(overlay);overlay.querySelector('[data-cancel-left]').onclick=()=>overlay.remove();overlay.querySelector('[data-confirm-left]').onclick=async()=>{const date=dateInput.value;if(!date){alert('Please choose a leaving date.');return}if(s.joining_date&&date<s.joining_date){alert('Leaving date cannot be before joining date.');return}const {error}=await sb.from('students').update({left_date:date,is_active:false}).eq('id',id);if(error){alert(error.message);return}overlay.remove();await load()}}
