 function eligibleStudents(){const date=$('attendanceDate').value;return students.filter(s=>s.is_active&&(!s.joining_date||s.joining_date<=date)&&(!s.left_date||s.left_date>=date));}
 function updateAttendanceSummary(){const ids=eligibleStudents().map(s=>s.id),vals=ids.map(id=>draftAttendance[id]||'');$('eligibleCount').textContent=ids.length;$('draftPresent').textContent=vals.filter(x=>x==='present').length;$('draftAbsent').textContent=vals.filter(x=>x==='absent').length;$('draftMissing').textContent=vals.filter(x=>!x).length;$('presentCount').textContent=vals.filter(x=>x==='present').length;$('absentCount').textContent=vals.filter(x=>x==='absent').length;$('totalCount').textContent=ids.length;}
