 async function recordsYear(year){const start=year+'-01-01',end=year+'-12-31';let all=[],from=0;while(true){const {data,error}=await sb.from('attendance').select('student_id,attendance_date,status').eq('organization_id',profile.organization_id).gte('attendance_date',start).lte('attendance_date',end).order('attendance_date').range(from,from+999);if(error)throw error;all=all.concat(data||[]);if(!data||data.length<1000)break;from+=1000;}return all;}
