 function daysInYear(y,s){const start=new Date(y,0,1),end=new Date(y,11,31);if(s.joining_date&&s.joining_date>y+'-12-31'||s.left_date&&s.left_date<y+'-01-01')return 0;const from=s.joining_date&&s.joining_date>y+'-01-01'?new Date(s.joining_date+'T00:00:00'):start,to=s.left_date&&s.left_date<y+'-12-31'?new Date(s.left_date+'T00:00:00'):end;return Math.max(0,Math.floor((to-from)/86400000)+1);}
