  if(['admin','teacher'].includes(role)&&['super_admin','platform_admin'].includes(profile?.role)&&!$('newUserOrganization')?.value){say('createUserMessage','Choose the organisation for this account.');return}if(role==='admin'&&!email&&!phone){say('createUserMessage','For an Admin account, enter at least one contact method: phone/WhatsApp or email. Phone is preferred.');return}
